// # the sibling arms of one `if` bind a local together, whichever is read
// # first: a literal arm beside a wider typed arm takes the typed arm's type
// # (int64, int, float), and typed arms join (int8 and int16 give int16). The
// # int64 product shows the width: 3000000000 is no int32. The same annotation
// # in both arms is one first binding, not a later annotation
// def arm_join(c: bool, v: int64, wide: float) -> None:
//     if c:
//         a = int64(3)  # tpyc: type(int64)
//     else:
//         a = 3  # tpyc: type(int64)
//     if c:
//         b = 3  # tpyc: type(int64)
//     else:
//         b = v  # tpyc: type(int64)
//     if c:
//         n = 0  # tpyc: type(int)
//     else:
//         n = big()  # tpyc: type(int)
//     if c:
//         m = big()  # tpyc: type(int)
//     else:
//         m = 0  # tpyc: type(int)
//     if c:
//         p = int8(3)  # tpyc: type(int16)
//     else:
//         p = int16(4)  # tpyc: type(int16)
//     if c:
//         q = int16(4)  # tpyc: type(int16)
//     else:
//         q = int8(3)  # tpyc: type(int16)
//     if c:
//         f = wide  # tpyc: type(float)
//     else:
//         f = 0.5  # tpyc: type(float)
//     if c:
//         r: int16 = 1  # tpyc: ok
//     else:
//         r: int16 = 2  # tpyc: ok
//     print("arm_join", a * 1_000_000_000, b * 1_000_000_000, n, m, p, q, f, r)
void arm_join(bool c, int64_t v, double wide) {
    int64_t a;
    if (c) {
        a = 3;
    } else {
        a = 3;
    }
    int64_t b;
    if (c) {
        b = 3;
    } else {
        b = v;
    }
    ::tpy::BigInt n;
    if (c) {
        n = ::tpy::BigInt(0);
    } else {
        n = ::tpyapp::main::big();
    }
    ::tpy::BigInt m;
    if (c) {
        m = ::tpyapp::main::big();
    } else {
        m = ::tpy::BigInt(0);
    }
    int16_t p;
    if (c) {
        p = static_cast<int16_t>(3);
    } else {
        p = 4;
    }
    int16_t q;
    if (c) {
        q = 4;
    } else {
        q = static_cast<int16_t>(3);
    }
    double f;
    if (c) {
        f = wide;
    } else {
        f = 0.5;
    }
    int16_t r;
    if (c) {
        r = 1;
    } else {
        r = 2;
    }
    std::cout << "arm_join" << " " << (::tpy::mul_check<int64_t>(a, 1000000000)) << " " << (::tpy::mul_check<int64_t>(b, 1000000000)) << " " << n << " " << m << " " << p << " " << q << " " << ::tpy::print_float(f) << " " << r << "\n" << ::tpy::check_signals;
}


